def query_from_point(
    self, x: float, y: float, dest_idx: int, slip_base: Dict[str, float]
) -> Tuple[int, float, int]:
    """Return (ticks, energy, best_first_vertex) from (x, y) to dest_idx."""
    dx, dy = self.dest_coords[dest_idx]
    direct_d = math.hypot(dx - x, dy - y)
    if direct_d < 0.15:
        return (0, 0.0, -1)
    if direct_d <= 8.0:
        met = self.segment_metrics(x, y, dx, dy, slip_base, max_allowed_slope=0.345)
        if met is not None:
            _, tk, en = met
            return (max(1, int(math.ceil(tk * 1.04 + 0.25))), en * 1.04, -1)

    i0, j0, _, _ = self.surface.locate(x, y)
    dc = self.dist_c[dest_idx]
    dt = self.dist_t[dest_idx]
    de = self.dist_e[dest_idx]
    best_c = 1e18
    best_t = 999
    best_e = 999.0
    best_v = -1

    for dj in (-1, 0, 1, 2):
        for di in (-1, 0, 1, 2):
            ci, cj = i0 + di, j0 + dj
            if 0 <= ci < self.nx and 0 <= cj < self.ny:
                v = cj * self.nx + ci
                if dc[v] >= 1e17:
                    continue
                vx, vy = ci * self.cell, cj * self.cell
                if math.hypot(vx - x, vy - y) < 0.1:
                    c0, tk0, en0 = 0.0, 0.0, 0.0
                else:
                    met = self.segment_metrics(x, y, vx, vy, slip_base, max_allowed_slope=0.345)
                    if met is None:
                        continue
                    c0, tk0, en0 = met
                tot_c = c0 + dc[v]
                if tot_c < best_c:
                    best_c = tot_c
                    best_t = max(1, int(math.ceil((tk0 + dt[v]) * 1.04 + 0.3)))
                    best_e = (en0 + de[v]) * 1.04
                    best_v = v

    if best_v == -1:
        # Fallback nearest vertex
        ci = min(self.nx - 1, max(0, int(round(x / self.cell))))
        cj = min(self.ny - 1, max(0, int(round(y / self.cell))))
        v = cj * self.nx + ci
        best_t = max(1, int(math.ceil(dt[v] * 1.05 + 1.0))) if dt[v] < 1e17 else 999
        best_e = de[v] * 1.05 if de[v] < 1e17 else 999.0
        best_v = v

    return (best_t, best_e, best_v)

