def _is_drive_robustly_safe(
    self, x: float, y: float, cmd_h: float, cmd_m: float
) -> bool:
    """Check if drive is safe against heading errors and position offsets."""
    surf = self.surface
    slip = self.estimator.est_slip
    bias = self.estimator.last_bias
    for dh in (0.0, -4.5, 4.5):
        for ds in (0.0, -0.02):
            r = drive(surf, PHYSICS, x, y, cmd_h + bias + dh, cmd_m, slip, ds)
            if r["stop"] is not None:
                return False
            if surf.slope(r["x"], r["y"]) > 0.342:
                return False
    # Also test small start position perturbations along worst-case axis
    for dx, dy in ((0.45, 0.0), (-0.45, 0.0), (0.0, 0.45), (0.0, -0.45)):
        sx, sy = x + dx, y + dy
        if surf.inside(sx, sy) and surf.slope(sx, sy) <= 0.35:
            r = drive(surf, PHYSICS, sx, sy, cmd_h + bias, cmd_m, slip, 0.0)
            if r["stop"] is not None:
                return False
    return True

def _compute_drive_command(
    self, x: float, y: float, wx: float, wy: float, exact_stop: bool
) -> Dict[str, Any]:
    """Compute optimal and safe (heading_deg, metres) from (x, y) toward (wx, wy)."""
    surf = self.surface
    slip = self.estimator.est_slip
    bias = self.estimator.last_bias
    dx, dy = wx - x, wy - y
    dist = math.hypot(dx, dy)
    if dist < 0.08:
        return {"action": "wait"}

    target_angle = math.degrees(math.atan2(dy, dx)) % 360.0
    # Initial guess for command heading and distance
    _, gx, gy, code = surf.sample(x, y)
    tname = TERRAIN_CODES[code]
    rad = math.radians(target_angle)
    grade = gx * math.cos(rad) + gy * math.sin(rad)
    slp = min(0.90, max(0.0, slip[tname] + PHYSICS["slip_grade_gain"][tname] * max(0.0, grade)))
    cmd_m = min(5.0, dist / max(0.15, 1.0 - slp)) if exact_stop else 5.0
    cmd_h = (target_angle - bias) % 360.0

    # 2-step iterative refinement using exact drive() model
    for _ in range(3):
        r = drive(surf, PHYSICS, x, y, cmd_h + bias, cmd_m, slip, 0.0)
        if r["stop"] is not None or r["ground"] < 1e-4:
            break
        moved_angle = math.degrees(math.atan2(r["y"] - y, r["x"] - x)) % 360.0
        ang_err = ((target_angle - moved_angle + 180.0) % 360.0) - 180.0
        cmd_h = (cmd_h + ang_err) % 360.0
        if exact_stop:
            cmd_m = min(5.0, max(0.1, cmd_m * (dist / r["ground"])))

    # If exact_stop and 2 steps away (e.g. dist is 5.2m so 5.0m leaves 0.4m), cap first step so both steps are balanced
    if exact_stop:
